import { chat } from "@voxta";
import './mood';
import { startGenerating, startSpeaking, doneSpeaking } from './speech';
import { showSubtitles, playTimelineAnimation } from './vam';

function canPlayAnimation() {
  // Check if the flag `Voxta_states_blocked` is NOT set
  return !chat.hasFlag('Voxta_states_blocked');
}

chat.addEventListener("transcriptionStarted", (e) => {
  if (canPlayAnimation()) {
    playTimelineAnimation('VS_listening', { randomInGroup: true });
  }
});

chat.addEventListener("transcriptionFinished", (e) => {
  if (!e.text && canPlayAnimation()) {
    playTimelineAnimation('VS_idle');
  }
});

chat.addEventListener("userMessageReceived", (e) => {
  showSubtitles(e.message.text, 'User');
});

chat.addEventListener("generating", (e) => {
  startGenerating();
  if (canPlayAnimation()) {
    playTimelineAnimation('VS_thinking', { randomInGroup: true });
  }
});

chat.addEventListener("speechStart", (e) => {
  const firstSpeech = startSpeaking();
  if (firstSpeech && canPlayAnimation()) {
    playTimelineAnimation('VS_speaking', { randomInGroup: true });
  }
  showSubtitles(e.message.text, 'Character');
});

chat.addEventListener("speechComplete", (e) => {
  if (canPlayAnimation()) {
    playTimelineAnimation('VS_idle');
  }
  const hasSpoken = doneSpeaking();
  if (!hasSpoken) {
    showSubtitles(e.message.text, 'Character');
  }
});

import { chat } from "@voxta";

let isSpeaking = false;
let isSpeakingStarted = false;
let queue = [];

export function startGenerating() {
  isSpeaking = true;
  isSpeakingStarted = false;
}

export function startSpeaking() {
  let wasSpeaking = isSpeakingStarted;
  isSpeakingStarted = true;
  return !wasSpeaking;
}

export function doneSpeaking() {
  console.log('speaking done: ' + isSpeakingStarted);
  const hasSpoken = isSpeakingStarted;
  isSpeaking = false;
  isSpeakingStarted = false;
  if (!queue.length) return hasSpoken;
  const toExecute = [...queue];
  queue = [];
  toExecute.forEach(fn => fn());
  return hasSpoken;
}

export function runAfterSpeech(fn) {
  if (!isSpeaking) {
    fn();
  } else {
    queue.push(fn);
  }
}

import { chat } from "@voxta";
import { runAfterSpeech } from './speech';

// Set to false if this scene has no "Overlays" atom (otherwise VaM logs an error for every subtitle).
const SHOW_SUBTITLES = false;

const overlays = {
  atom: 'Overlays',
  storable: 'plugin#0_VAMOverlaysPlugin.VAMOverlays'
};

// Timeline animations are switched off: ARDY (the BVH player) drives the body now, and this scene has no
// Timeline plugin, so every call used to log an error in VaM.
export function playTimelineAnimation(name, options) {
  return;
}

export function showSubtitles(text, who) {
  if (!SHOW_SUBTITLES) return;
  chat.appTrigger('String', overlays.atom, overlays.storable, "Set and show subtitles", text);
  const color = who === 'User' ? '#90CDE0' : '#E5BEBE';
  chat.appTrigger('Color', overlays.atom, overlays.storable, "Subtitles Color", color);
}

import { chat } from "@voxta";
console.log("MOOD script v43 loaded: speech in asterisks is not a stage direction (\"** Oh yes **\" and first-person lines are left alone); v42: the face channel (VaMRT_Face gets the six mood axes as \"Mood\", her *face cues* as \"Face Cue\", speech as \"Speaking\"); v41: her own *stage directions* move her (NARR: walks to scene objects or to Todd with the manner she gave, postures in the imperative; face/voice logged only); \"get on your knees\" is a request; v40: the event lines are stage directions, never spoken (a standing rule for the model); an event-driven turn counts as an unnamed touch instead of a guessed thigh touch; v39: no sample sentence in the voice hint (she was repeating it); v38: firm voice hints in strong states, per-sentence tags (Voxta voices each sentence on its own); v37: test presets (say 'mood test cold/hurt/furious/warm/aroused/tired/reset'), the 'fond of' line no longer flickers; v36: voice hints back on, mapped to the ElevenLabs voice's styles (warm, playful, whispering, cold, angry, sad, tired...); v35: the wardrobe follows her own word ('I'll remove my skirt') and 'pick another piece to remove'; v34: voice style tags off by default (Ava's voice expresses nothing, so they only leaked into her lines); v33: the mood drives E-Motion's face through its real levers (smile ceiling/offset, valence and arousal speed, mood degrade, expression chance, breathing); v32: her own anger is heard (accusations, 'not cool', 'the hell'), a heated message of his counts, a stale 'she says' expires; v31: compliments warm her but do not arouse her (desire, touch and intimacy do); arousal holds while the moment is intimate and fades fast when it is not; a lively / mellow / charged line so a good mood shows too; optional Valence/Arousal push to E-Motion (emotionMood)");
// ===================== MOOD CORE v2 =====================
// Character state kept by CODE, not by the model. The model only ever sees a tiny, rarely-changing text.
//
//  layers:   1) six mood axes with decay          (fast, minutes)
//            2) a small ledger of recent events    (slow, ~20 min half-life) - explains WHY she feels it
//            3) a stance derived from the above    (engage / playful / guarded / withdrawn / disengage)
//  outputs:  a) ONE short context line for the model (hard capped, empty when nothing is going on)
//            b) E-Motion sliders
//            c) chat 'mood_stance' for the action scripts (movement policy)
//
// TOKEN BUDGET: the injected text is built from fixed phrases, picks at most stance + one reason + one tiredness
// clause, is capped at MOOD_CFG.maxContextChars, and only changes when the stance or a flag changes (hysteresis),
// so the model's prompt cache stays valid and the context cannot grow or drift. Numbers are never shown to the model.
const MOOD_CFG = {
  // where she settles when nothing is happening (warmth -1..1, the others 0..1)
  baseline: { warmth: 0.25, irritation: 0.0, energy: 0.5, comfort: 0.8, hurt: 0.0, arousal: 0.1 },
  // how slowly each feeling fades, in seconds (bigger = lingers longer). hurt lingers longest.
  tau: { warmth: 600, irritation: 300, energy: 300, comfort: 420, hurt: 1200, arousal: 240 },
  // the moment: how intimate things are right now (touch, desire, undressing, intimate talk raise it; it fades over ~15 minutes).
  // Arousal settles toward baseline + heatLift * heat and fades slowly while the moment is intimate, fast when it is not.
  heatTau: 900, heatLift: 0.45, heatHold: 1500,
  // ledger: how many events are remembered, how fast they fade (seconds, half-life), and when one is worth mentioning
  ledgerMax: 6, ledgerHalfLife: 1200, ledgerDrop: 0.1, reasonOn: 0.35, reasonOff: 0.2,
  // stance hysteresis: once in a stance, it takes this much less to stay in it
  stanceMargin: 0.08,
  // the body (motion prompter) is told of a stance/energy change at most this often, seconds
  bodyCooldown: 15,
  // her own tone feeds back: a snap of hers while she was fine raises irritation, but never past this on its own (no spiral);
  // kind words of hers raise warmth, never past selfWarmCap
  selfIrritationCap: 0.45, selfWarmCap: 0.6,
  // rapport: a slow memory of how the two of them get on, within this chat; it moves her warmth and comfort baselines
  rapportStep: 0.015, rapportHit: 0.04, rapportWarmth: 0.3, rapportComfort: 0.1,
  // when the user has said nothing for this long (seconds) she notices, and says so once when he is back
  waitingAfter: 240, waitingLong: 900,
  // explicit, vulgar language is hers to use only when the moment is like that (arousal at least this), never as a default
  explicitAt: 0.45,
  // the model never receives more than this many characters of mood text
  maxContextChars: 420,
  // E-Motion: put the plugin's id here (as shown in VaM's plugin list, e.g. 'plugin#3_VRAdultFun.E-Motion').
  // While emotionLive is false nothing is sent; the log only says what would be sent.
  emotionPlugin: 'plugin#8_VRAdultFun.EmotionEngine',
  emotionAtom: 'Person',
  emotionLive: false,      // E-Motion is replaced by VaMRT_Face (v42); set true again only if E-Motion is back on the atom
  // VaMRT_Face (v42): the plugin id as the BVH Player's "Plugin IDs" box shows it (e.g. 'plugin#3_VaMRT.VaMRT_Face'). It receives the six
  // mood axes ("Mood"), her own face cues from her *stage directions* ("Face Cue") and whether she is speaking ("Speaking").
  facePlugin: 'plugin#3_VaMRT.VaMRT_Face',
  faceLive: true,
  // E-Motion's Valence/Arousal are OUTPUTS of its own engine (overwritten every frame: EmotionEngine.cs line 2651), so they cannot be
  // set from here. What can: the levers its engine runs on. emotionFace pushes them from the mood - how much she may smile and
  // whether the corners of her mouth sit up or down, how readily she brightens or gets excited, how fast a good mood drains,
  // how often her expression changes, how she breathes. E-Motion has no unhappy faces of its own; "cross" here means: no smile,
  // mouth corners down, brightness drains fast, fewer expression changes, no eye contact.
  emotionFace: true,
  // the "Voice: begin every reply with <whispering>" line. Only useful when the character's voice has expressions set up in
  // Voxta; the 2 Nov log says "Voice Voxta_F_Liberty.wav of Ava expresses nothing", so the tags did nothing except leak into her
  // spoken text ("[thrilled] Hm, good question"). Set true once the voice has expressions.
  voiceHints: true,
  // the styles the voice offers (from the Voxta log line "Voice ... of Ava can express: ..."); a hint names only one of these
  voiceStyles: ['happy', 'playful', 'warm', 'sad', 'nervous', 'angry', 'cold', 'tired', 'curious', 'gasp', 'sigh', 'laughs', 'whispering', 'moaning', 'painfully', 'whiny', 'resigned tone', 'timidly'],
  // when she says she is leaving ("I'm going to my room"), her body walks away too; at most once per cooldown (seconds)
  leaveSync: true,
  leaveCooldown: 120,
  bvhPlugin: 'plugin#1_ElkVR.BVHPlayer',
  log: true
};

const MOOD_DEBUG = true;   // logs what each event carried (message role, whether voice markers are in the text); set false once everything works
function moodDebug(msg) { if (MOOD_DEBUG) console.log('MOOD debug ' + msg); }
function moodLog(msg) { if (MOOD_CFG.log) console.log('MOOD ' + msg); }
function moodClamp(x, lo, hi) { return Math.max(lo, Math.min(hi, x)); }

function moodDefaults(now) {
  const b = MOOD_CFG.baseline;
  return { v: 4, w: b.warmth, i: b.irritation, e: b.energy, c: b.comfort, h: b.hurt, a: b.arousal, t: now,
           feeling: '', feelingT: -1e9, st: 'engage', tired: false, lively: false, charged: false, rk: '', L: [], r: 0, cmd: 0, wait: 0, ht: 0, hf: 0 };
}

function moodRead(chat, now) {
  let s = null;
  try {
    const raw = chat.get('mood_state', '');
    if (raw) s = JSON.parse(raw);
  } catch (err) { s = null; }
  if (!s || typeof s.w !== 'number') return moodDefaults(now);
  // upgrade a v1 state (four axes) without losing it
  const d = moodDefaults(now);
  for (const k of Object.keys(d)) { if (s[k] === undefined) s[k] = d[k]; }
  if (!Array.isArray(s.L)) s.L = [];
  return s;
}

function moodWrite(chat, s) {
  try { chat.set('mood_state', JSON.stringify(s)); } catch (err) { moodLog('could not save state: ' + err); }
}

// let every feeling drift back toward its baseline, and every remembered event fade, for the time that has passed
function moodDecay(s, now) {
  const dt = Math.max(0, now - s.t);
  const b = MOOD_CFG.baseline, k = MOOD_CFG.tau;
  const r = moodClamp(s.r || 0, 0, 1);
  const bw = moodClamp(b.warmth + MOOD_CFG.rapportWarmth * r, -1, 1), bc = moodClamp(b.comfort + MOOD_CFG.rapportComfort * r, 0, 1);
  s.w = bw + (s.w - bw) * Math.exp(-dt / k.warmth);
  s.i = b.irritation + (s.i - b.irritation) * Math.exp(-dt / k.irritation);
  s.e = b.energy + (s.e - b.energy) * Math.exp(-dt / k.energy);
  s.c = bc + (s.c - bc) * Math.exp(-dt / k.comfort);
  s.h = b.hurt + (s.h - b.hurt) * Math.exp(-dt / k.hurt);
  // the moment cools, but never below what the wardrobe says (being undressed keeps a floor under it)
  s.ht = Math.max(s.hf || 0, (s.ht || 0) * Math.exp(-dt / MOOD_CFG.heatTau));
  const ba = moodClamp(b.arousal + MOOD_CFG.heatLift * s.ht, 0, 1), ta = k.arousal + MOOD_CFG.heatHold * s.ht;
  s.a = ba + (s.a - ba) * Math.exp(-dt / ta);
  const f = Math.pow(0.5, dt / MOOD_CFG.ledgerHalfLife);
  for (const x of s.L) x.m *= f;
  s.L = s.L.filter(x => x.m >= MOOD_CFG.ledgerDrop);
  s.t = now;
  return s;
}

// ---- LEDGER: what happened recently and how much it still weighs (kept in code, never sent as a list) ----
const MOOD_OFFENSES = ['hostile', 'rude', 'cold'];
function ledgerAdd(s, kind, mag, now) {
  s.L.push({ k: kind, m: moodClamp(mag, 0, 1), t: Math.round(now) });
  if (s.L.length > MOOD_CFG.ledgerMax) {
    let wi = 0;
    for (let j = 1; j < s.L.length; j++) { if (s.L[j].m < s.L[wi].m) wi = j; }
    s.L.splice(wi, 1);
  }
}
function ledgerActive(s) { return s.L.filter(x => MOOD_OFFENSES.indexOf(x.k) >= 0 && x.m >= 0.2).length; }
function ledgerTop(s) {
  let top = null;
  for (const x of s.L) { if (MOOD_OFFENSES.indexOf(x.k) >= 0 && (!top || x.m > top.m)) top = x; }
  return top;
}
// an apology settles what it can: recent offences weigh much less afterwards
function ledgerForgive(s, factor) { for (const x of s.L) { if (MOOD_OFFENSES.indexOf(x.k) >= 0) x.m *= factor; } }

// ---- What the user's words do (read by code, before she answers, so her very next reply already reflects it) ----
// each list is a regex of words; hits aimed at her ("you...") count fully, general remarks count about a third
const MOOD_WORDS = {
  hostile: /\b(stupid|idiot|moron|dumb|useless|worthless|pathetic|loser|disgusting|ugly|hate you|shut up|shut the (?:f|hell)|stfu|fuck you|fuck off|bitch|slut|whore|creep|freak|trash|garbage|get lost|go away|sick of (?:you|listening|hearing)|nobody (?:likes|cares|wants)|no one (?:likes|cares|wants))\b/gi,
  rude: /\b(boring|not (?:that|very|even|at all|so) (?:interesting|funny|smart|pretty|attractive|special|clever|good)|uninteresting|you suck|nobody asked|so dull|annoying|irritating|obnoxious|lame|cringe|clueless|stuck up|full of yourself|nothing better to do|waste of (?:time|space)|whatever|don'?t care|not interested|so what|who asked|grow up|get over yourself|spare me)\b/gi,
  cold: /\b(leave me alone|i'?m busy|i'?m tired of (?:you|this)|whatever you say)\b|^\W*(?:fine then|if you say so|i guess|meh|not really|whatever)\W*$/gi,
  praise: /\b(beauti\w*|gorgeous|stunning|pretty|lovel\w*|amazing|wonderful|cute|adorable|smart|clever|funny|sweet\w*|kind\w*|talent\w*|perfect|incredible|fantastic|attractive|sexy|handsome|love\w*|adore\w*|kiss\w*|cuddl\w*|snuggl\w*|hug\w*|i like you|care (?:about|for) you|fond of you|babe|baby|darling|sweetheart|honey|good girl|exciting part of my day|seeing you|miss(?:ed)? you|can'?t (?:keep|take) my eyes off|happy to see you|glad you'?re here|enjoy (?:spending|being|my time|the time|every minute) with you|like being (?:with|around) you|you make me (?:happy|smile|laugh)|love (?:spending|being) (?:time )?with you|good company|lucky to have you|my favou?rite person)\b/gi,
  // a compliment on her looks warms her; it is not what arouses her (desire, touch and intimacy are, below)
  compliment: /\b(sexy|gorgeous|stunning|attractive|handsome|beautiful|hot|pretty|cute|good[- ]looking|nice (?:body|legs|ass|eyes|smile))\b/gi,
  desire: /\b(turn(?:s|ed|ing)? me on|i want you|want you (?:so|right|now|bad)|need you|miss(?:ed)? you|can'?t (?:keep|take) my eyes off|drives? me (?:crazy|wild)|can'?t stop (?:thinking|looking)|make me (?:hard|wet)|i'?m (?:so )?(?:hard|wet|horny|turned on)|you (?:make|get) me (?:hard|wet|horny))\b/gi,
  thanks: /\b(thanks|thank you|appreciate|grateful)\b/gi,
  apology: /\b(sorry|apolog\w*|forgive me|my bad|didn'?t mean|i was wrong|uncalled for|my fault)\b/gi
};
const MOOD_HEATED = /\?\?|\b(?:excuse me|what do you mean|are you (?:serious|kidding)|seriously|unbelievable|calm down|whatever|fine!|so what|i was (?:just |only )?trying)\b/i;
const MOOD_YOU = /\b(you|you'?re|youre|your|yours|u|ur|yourself)\b/i;

function moodHits(text, re) {
  const t = String(text || '');
  let n = 0, m;
  re.lastIndex = 0;
  while ((m = re.exec(t)) !== null) {
    const before = t.slice(Math.max(0, m.index - 14), m.index).toLowerCase();
    if (/(not|n't|never|no|isn't|aren't|wasn't|ain't)\s+(?:\w+\s+){0,1}$/.test(before)) continue; // negated: "you're not stupid"
    n++;
    if (m.index === re.lastIndex) re.lastIndex++;
  }
  return n;
}

// how the user's message lands: returns { label, mag, d:[warmth, irritation, comfort, energy, hurt, arousal] } or null
// s is read only (to know how close they are and how many offences are still fresh)
function moodReadText(text, s) {
  const t = String(text || '').trim();
  if (!t) return null;
  const you = MOOD_YOU.test(t) ? 1 : 0.3;
  const loud = (t.match(/!/g) || []).length >= 2 || (t.length > 8 && t === t.toUpperCase() && /[A-Z]/.test(t)) ? 1.25 : 1;
  const hostile = moodHits(t, MOOD_WORDS.hostile), rude = moodHits(t, MOOD_WORDS.rude), cold = moodHits(t, MOOD_WORDS.cold);
  if (hostile || rude || cold) {
    let d, label, mag;
    //            warmth irrit  comf   energy hurt   arousal
    if (hostile) { d = [-0.35, 0.45, -0.25, 0.10, 0.30, -0.20]; label = 'hostile'; mag = 0.9; }
    else if (rude) { d = [-0.25, 0.30, -0.15, 0.05, 0.15, -0.12]; label = 'rude'; mag = 0.6; }
    else { d = [-0.12, 0.08, -0.05, -0.05, 0.06, -0.05]; label = 'cold'; mag = 0.3; }
    const extra = 1 + 0.25 * Math.min(2, Math.max(0, hostile + rude - 1));
    // repeating an offence while the last one is still fresh hits harder (a grudge builds), and it hurts more when they are close
    const rep = 1 + 0.2 * Math.min(3, s ? ledgerActive(s) : 0);
    const close = s ? (0.6 + 0.6 * moodClamp((s.w + 1) / 2, 0, 1)) : 1;
    const k = you * loud * extra * rep;
    const dd = d.map(x => x * k);
    dd[4] = d[4] * k * close;
    return { label: label, mag: mag * moodClamp(you * loud, 0.3, 1), d: dd };
  }
  const apology = moodHits(t, MOOD_WORDS.apology);
  if (apology) return { label: 'apologetic', mag: 0.3, d: [0.12, -0.12, 0.08, 0, -0.12, 0] };
  // raised voice without an insult ("What do you mean?? So EXCUSE me for caring"): it lands as heat, not as an offence
  if ((loud > 1 || /\b[A-Z]{4,}\b/.test(t)) && MOOD_HEATED.test(t)) return { label: 'heated', mag: 0.15, d: [-0.05, 0.08, -0.03, 0.08, 0.03, -0.05] };
  // being ordered about: the third bare order in a row (and every one after) wears on her a little; a softened request does the opposite
  if (MOOD_ORDER.test(t) && !MOOD_SOFT.test(t)) {
    const n = s ? (s.cmd || 0) + 1 : 1;
    if (s) s.cmd = n;
    if (n >= 3) return { label: 'bossed', mag: 0.15, d: [-0.04, 0.05, -0.02, 0, 0.01, 0] };
    return null;
  }
  if (s) s.cmd = 0;
  if (MOOD_CLOSE.test(t)) return { label: 'close', mag: 0.1, d: [0.05, -0.02, 0.03, 0.02, -0.01, 0.03] };
  if (MOOD_SOFT.test(t) && /\b(?:you|your)\b/i.test(t)) return { label: 'polite', mag: 0.05, d: [0.03, -0.03, 0.02, 0, 0, 0] };
  const praise = moodHits(t, MOOD_WORDS.praise);
  if (praise) {
    const k = Math.min(2, praise);
    const fl = moodHits(t, MOOD_WORDS.desire) ? 1 : 0;
    const cp = fl ? 0 : (moodHits(t, MOOD_WORDS.compliment) ? 1 : 0);
    return { label: fl ? 'flirty' : (cp ? 'a compliment' : 'praise'), mag: 0.2, d: [0.08 * k, -0.05 * k, 0.04 * k, 0.03 * k, -0.03 * k, 0] };
  }
  if (moodHits(t, MOOD_WORDS.thanks)) return { label: 'thankful', mag: 0.1, d: [0.08, -0.05, 0.04, 0, -0.02, 0] };
  return null;
}

// how she herself sounds: her reply is the model's own reading of her state, so it feeds back into the numbers (capped, so a random snap
// cannot talk her into a rage by itself). Returns 'hostile' | 'refusing' | 'warm' | 'playful' | null.
const HER_HOSTILE = /\b(?:fuck you|fuck off|screw you|piss off|shut up|go to hell|get out|get lost|leave me alone|don'?t (?:command|order|boss|tell) me|like (?:a|some|some sort of|your) (?:dog|pet|toy|servant|slave|puppet)|not your (?:toy|pet|dog|servant|slave|puppet)|i'?m not (?:some|your) (?:toy|pet|dog)|how dare you|you (?:disgust|bore) me|i hate (?:you|this)|stop pretending|don'?t touch me|back off|i'?m (?:done|out of here|leaving))\b/i;
// upset without swearing: accusations and reproach ("you had no right", "that's not cool", "the hell, Todd?", "you invaded my trust")
const HER_UPSET = /\b(?:you had no right|had no right|that'?s not (?:cool|okay|ok|fair|funny)|not cool|the hell|what the hell|what the fuck|how could you|how dare you|i can'?t believe you|you should'?ve|you should have|invasion of (?:my )?privacy|invaded my|betray\w*|you (?:lied|cheated|used) (?:to )?me|deal with it|i'?m not (?:happy|okay|ok|fine) with|that hurts?|you hurt me|unbelievable|seriously\??|are you kidding|get out of my|don'?t (?:ever )?(?:do|say) that again|you went through my)\b/i;
const HER_REFUSE = /\b(?:no way|not a chance|not happening|forget it|dream on|in your dreams|i refuse|absolutely not|certainly not|i'?m not (?:going to|gonna|doing)|i won'?t|i will not|not (?:now|tonight|today)|earn it|you'?ll have to earn|make me)\b|^\W*no\b(?! need| problem| worries| rush| idea| one|,? not at all)/i;
const HER_WARM = /\b(?:you'?re (?:so )?(?:sweet|cute|adorable|lovely|kind|a sweetheart|the best)|i (?:like|love|adore|missed) (?:you|that|this|it when|being here)|glad you'?re here|good to see you|come (?:here|closer|sit)|i'?m (?:so )?(?:happy|glad|lucky)|sweetheart|darling|honey|babe|that'?s (?:so )?sweet|thank you|i trust you|i'?m (?:all )?yours|anything for you|of course)\b/i;
const HER_PLAYFUL = /\b(?:careful|cheeky|tease|teasing|maybe|we'?ll see|i might|if you'?re lucky|is that so|oh really|make me|you wish|nice try|show off|smooth|cute of you)\b|\bha(?:ha)+\b/i;
function moodReadHer(text) {
  const t = String(text || '');
  if (HER_HOSTILE.test(t)) return 'hostile';
  if (HER_UPSET.test(t)) return 'upset';
  if (HER_REFUSE.test(t)) return 'refusing';
  if (HER_WARM.test(t)) return 'warm';
  if (HER_PLAYFUL.test(t)) return 'playful';
  return null;
}
function moodApplyHer(s, tone) {
  const cap = MOOD_CFG.selfIrritationCap;
  if (tone === 'hostile') {
    // what she said is now how she feels: enough to turn her guarded, not enough to turn her away on its own
