  else if (st === 'playful') parts.push(s.a >= 0.55 ? name + ' is warm, playful and clearly attracted to ' + user : name + ' is relaxed, warm and playful with ' + user);
  else {   // engage: she is fine, and the model is told so, otherwise it invents drama of its own
    if (s.fond) parts.push(name + ' is fond of ' + user + ' and at ease with him; she goes along with what he asks and teases him while she does it');
    else parts.push(name + ' is relaxed and at ease with ' + user + ' and goes along with reasonable requests; teasing is fine, hostility is not');
  }
  if (st !== 'engage' && st !== 'playful' && s.rk) {
    parts.push(s.rk === 'hostile' ? 'what ' + user + ' said earlier still stings' : 'she has not forgotten ' + user + "'s rude remark");
  }
  if (s.tired) parts.push('she is tired');
  else if (s.lively && (st === 'engage' || st === 'playful')) parts.push('she is lively and quick to laugh');
  else if (s.e < 0.38 && (st === 'engage' || st === 'playful')) parts.push('she is mellow and unhurried');
  if (s.charged && (st === 'engage' || st === 'playful')) parts.push(s.a >= MOOD_CFG.explicitAt ? 'there is real heat between them' : 'there is a charge between them and she flirts back');
  if (s.a >= MOOD_CFG.explicitAt && st !== 'disengage' && st !== 'withdrawn') parts.push('she is free to be explicit and vulgar now');
  const vh = MOOD_CFG.voiceHints ? voiceHint(s) : '';
  if (!parts.length && !vh) return '';
  let text = parts.length ? parts.join('; ') : '';
  if (text) text = text.charAt(0).toUpperCase() + text.slice(1) + '. Show it in tone and body language, never announce it.';
  text = (text + vh).trim();
  if (text.length > MOOD_CFG.maxContextChars) text = text.slice(0, MOOD_CFG.maxContextChars - 1).replace(/[,;]?\s*\S*$/, '') + '.';
  return text;
}

// ---- AGREEMENTS: plans and rules the two of them settled ("drinks this afternoon", "the question game: ... deal?"). A 12B model loses
// these within a few turns even though they are in the history, so code keeps the last few and shows them in one short line.
const AGREE_CUE = /\b(?:let'?s|shall we|we (?:could|should|will|'ll)|wanna|want to|how about (?:we|going|a)|would you like to|deal\??|the rules? (?:are|is)|here'?s the (?:game|deal|plan)|i have an idea|tonight|this (?:afternoon|evening|weekend)|later|after this|first .* then)\b/i;
const AGREE_YES = /\b(?:sure|sounds? (?:fun|good|great|like a plan|interesting)|deal|alright|all right|okay|ok|fine|let'?s do (?:it|this)|i'?m in|i'?d love to|count me in|you'?re on|i'?ll bite|yes|yeah|why not|can'?t wait)\b/i;
const AGREE_NO = /\b(?:no way|not a chance|nope|nah|i'?d rather not|not tonight|maybe later|pass|forget it|i don'?t think so)\b/i;
function agreeRead(chat) { try { const a = JSON.parse(chat.get('agreed', '[]')); return Array.isArray(a) ? a : []; } catch (err) { return []; } }
function agreeWrite(chat, a) { try { chat.set('agreed', JSON.stringify(a.slice(-3))); } catch (err) {} }
function agreeOnUser(chat, text, now) {
  const t = String(text || '').trim();
  if (!AGREE_CUE.test(t) || t.length < 12 || /\?\s*$/.test(t) && !/\bdeal\?\s*$/i.test(t) && !/\b(?:would you like|wanna|want to|how about|shall we)\b/i.test(t)) { chat.set('agree_pending', ''); return; }
  chat.set('agree_pending', JSON.stringify({ text: t.slice(0, 180), t: now }));
}
function agreeOnReply(chat, reply, now) {
  let p = null; try { p = JSON.parse(chat.get('agree_pending', '') || 'null'); } catch (err) { p = null; }
  chat.set('agree_pending', '');
  if (!p || now - p.t > 120) return;
  const r = String(reply || '');
  if (AGREE_NO.test(r) || !AGREE_YES.test(r)) return;
  const a = agreeRead(chat).filter(x => x.text !== p.text);
  a.push({ text: p.text, t: Math.round(now) });
  agreeWrite(chat, a);
  moodLog('agreed: ' + p.text.slice(0, 80));
  agreeApply(chat, now);
}
function agreeApply(chat, now) {
  const a = agreeRead(chat).filter(x => now - x.t < 2400);   // 40 minutes
  agreeWrite(chat, a);
  const text = a.length ? ('Earlier Todd and Ava agreed on: ' + a.map(x => '"' + x.text + '"').join(' | ') + '. This still stands.') : '';
  let last = ''; try { last = chat.get('agreed_ctx', ''); } catch (err) {}
  if (text === last) return;
  try { if (text) chat.setContext('agreed', text); else chat.setContext('agreed'); chat.set('agreed_ctx', text); } catch (err) { moodLog('could not set agreed context: ' + err); }
}

// a note for ONE reply (cleared at the next user message): why her body did not do what he asked, or that he was gone a while
function moodNote(chat, text) {
  try {
    if (text) { chat.setContext('mood_note', text); chat.set('mood_note', text); moodLog('note -> ' + text); }
    else if (chat.get('mood_note', '')) { chat.setContext('mood_note'); chat.set('mood_note', ''); }
  } catch (err) { moodLog('could not set note: ' + err); }
}
function moodWaitingNote(chat, s, now) {
  let last = null;
  try { last = chat.get('user_t', null); } catch (err) {}
  if (last === null || last === undefined) return '';
  const gap = now - last;
  if (gap < MOOD_CFG.waitingAfter) return '';
  const mins = Math.max(1, Math.round(gap / 60));
  s.e = moodClamp(s.e - 0.1, 0, 1);   // waiting is dull
  if (gap >= MOOD_CFG.waitingLong) return 'Todd said nothing for about ' + mins + ' minutes; she noticed, and whatever she was doing meanwhile, she is not going to pretend she did not';
  return 'Todd was quiet for a few minutes; she noticed';
}

function moodApplyContext(chat, s) {
  const text = moodDescribe(s, chat);
  let last = '';
  try { last = chat.get('mood_context', ''); } catch (err) {}
  if (text === last) return text;
  try {
    if (text) chat.setContext('mood', text); else chat.setContext('mood');
    chat.set('mood_context', text);
    moodLog('context (' + text.length + ' chars) -> ' + (text || '(cleared)'));
  } catch (err) { moodLog('could not set context: ' + err); }
  return text;
}

// push the mood into E-Motion (only if its plugin id is filled in above and emotionLive is true)
// a value is re-sent only when it moved by at least this much (keeps the trigger traffic down)
const EMO_EPS = { 'Max Smile (Morphs)': 0.05, 'Smile Morphs Offset': 0.02, 'Valence Speed Mult': 0.15, 'Arousal Speed Mult': 0.2,
                  'Mood Degrade Speed Mult': 0.4, 'Expression Change Chance': 4, 'Breath Speed Mult': 0.1 };
function moodPushEmotion(chat, s) {
  const targets = {
    'Personality Extraversion': Math.round(moodClamp(50 + 40 * s.w - 25 * s.i - 15 * s.h, 5, 95)),
    'Personality Stableness': Math.round(moodClamp(50 - 30 * s.i - 15 * (1 - s.c) - 10 * s.h, 5, 95))
  };
  const r2 = x => Math.round(x * 100) / 100;
  if (MOOD_CFG.emotionFace) {
    const wp = Math.max(0, s.w);
    targets['Max Smile (Morphs)'] = r2(moodClamp(0.55 + 0.45 * wp - 0.6 * s.i - 0.5 * s.h, 0, 1));
    targets['Smile Morphs Offset'] = r2(moodClamp(0.06 * wp - 0.14 * s.i - 0.1 * s.h, -0.2, 0.08));
    targets['Valence Speed Mult'] = r2(moodClamp(1 + 1.5 * wp - 0.8 * s.i - 0.6 * s.h, 0.2, 3));
    targets['Arousal Speed Mult'] = r2(moodClamp(0.6 + 2.5 * s.a - 0.5 * s.i, 0.3, 4));
    targets['Mood Degrade Speed Mult'] = r2(moodClamp(1 + 6 * s.i + 4 * s.h - 0.5 * wp, 0.5, 10));
    targets['Expression Change Chance'] = Math.round(moodClamp(20 + 25 * s.e - 15 * s.i - 10 * s.h, 5, 60));
    targets['Breath Speed Mult'] = r2(moodClamp(1 + 0.5 * s.a + 0.3 * (s.e - 0.5) + 0.4 * s.i, 0.6, 2));
  }
  const avoid = (s.c < 0.45 || s.i > 0.6 || s.h > 0.5);
  let last = {};
  try { last = JSON.parse(chat.get('mood_pushed', '{}')) || {}; } catch (err) { last = {}; }
  const sent = {};
  const names = Object.keys(targets);
  for (const k of names) {
    const v = targets[k];
    const eps = EMO_EPS[k] !== undefined ? EMO_EPS[k] : 4;
    if (last[k] === undefined || Math.abs(last[k] - v) >= eps) {
      sent[k] = v;
      if (MOOD_CFG.emotionLive && MOOD_CFG.emotionPlugin) {
        try { chat.appTrigger('Float', MOOD_CFG.emotionAtom, MOOD_CFG.emotionPlugin, k, v); } catch (err) { moodLog('E-Motion send failed: ' + err); }
      }
      last[k] = v;
    }
  }
  if (last['Gaze Avoidance'] !== avoid) {
    sent['Gaze Avoidance'] = avoid;
    if (MOOD_CFG.emotionLive && MOOD_CFG.emotionPlugin) {
      try { chat.appTrigger('Bool', MOOD_CFG.emotionAtom, MOOD_CFG.emotionPlugin, 'Gaze Avoidance', avoid); } catch (err) { moodLog('E-Motion send failed: ' + err); }
    }
    last['Gaze Avoidance'] = avoid;
  }
  if (Object.keys(sent).length) {
    moodLog('E-Motion ' + (MOOD_CFG.emotionLive && MOOD_CFG.emotionPlugin ? 'sent ' : 'dry run, would send ') + JSON.stringify(sent));
    try { chat.set('mood_pushed', JSON.stringify(last)); } catch (err) {}
  }
}

function moodSummary(s) {
  const r = x => Math.round(x * 100) / 100;
  return s.st + ' | warmth ' + r(s.w) + ', irritation ' + r(s.i) + ', energy ' + r(s.e) + ', comfort ' + r(s.c) +
         ', hurt ' + r(s.h) + ', arousal ' + r(s.a) + ' (moment ' + r(s.ht || 0) + ')' + ', rapport ' + r(s.r || 0) + ', ledger ' + s.L.length + (s.feeling && s.t - s.feelingT < 600 ? ', she says: ' + s.feeling : '');
}

// her own words nudge her mood a little (at most once every 8 s), and a clear "I'm leaving" is followed by her body
function moodHearSelf(chat, text) {
  const f = moodReadSelf(text);
  if (f && chat.time - chat.get('self_t', -1e9) >= 8) {
    chat.set('self_t', chat.time);
    moodUpdate(chat, { ava_feeling: f, intensity: '3' }, null);
  }
  moodLeaveSync(chat, text);
}

// she says she is leaving: make the body agree with the words (once per cooldown)
const MOOD_LEAVE = /\b(?:i'?m|i am|i'?ll|i will|i'?m going to|i'?m gonna) (?:go(?:ing)? )?(?:to (?:my|the) (?:room|bedroom)|to bed|home|leave|leaving|walk(?:ing)? (?:out|away)|out of here)\b|\bi'?m (?:leaving|done here|done talking|out of here|outta here|storming off)\b|\bi'?m going to go (?:to (?:my|the) |now|home|upstairs|lie down|sleep|be alone)/i;
function moodLeaveSync(chat, text) {
  if (!MOOD_CFG.leaveSync || !MOOD_LEAVE.test(String(text || ''))) return;
  const now = chat.time;
  if (now - chat.get('leave_t', -1e9) < MOOD_CFG.leaveCooldown) return;
  chat.set('leave_t', now);
  moodLog('she is leaving, body follows -> ' + String(text).slice(0, 80));
  try {
    chat.appTrigger('Bool', MOOD_CFG.emotionAtom, 'geometry', 'useAdvancedColliders', false);
    chat.appTrigger('String', MOOD_CFG.emotionAtom, MOOD_CFG.bvhPlugin, 'Motion Request', 'walk away');
  } catch (err) { moodLog('leave failed: ' + err); }
}

// her body hears about her mood too: the motion prompter gets "[mood stance=... energy=...]" as a request of its own whenever the
// stance or the energy level changes (rarely, thanks to the hysteresis), and every movement request carries the same tag. The prompter
// (mood_style.py) turns it into the manner of her walks, dances and waves and into which idle motions she favours.
function moodEnergyLevel(s) { return s.e < 0.35 ? 'low' : (s.e > 0.65 ? 'high' : 'mid'); }
function moodPushBody(chat, s, now) {
  const level = moodEnergyLevel(s);
  chat.set('mood_energy', level);
  const key = s.st + '/' + level;
  if (key === String(chat.get('mood_body', '')) || now - chat.get('mood_body_t', -1e9) < MOOD_CFG.bodyCooldown) return;
  // (the prompter also learns the mood from the tag on every movement request, so a missed push only delays it)
  chat.set('mood_body', key);
  chat.set('mood_body_t', now);
  chat.appTrigger('String', MOOD_CFG.emotionAtom, MOOD_CFG.bvhPlugin, 'Motion Request', '[mood stance=' + s.st + ' energy=' + level + ']');
  moodLog('body told: ' + key);
}

// v42: the six axes go to VaMRT_Face as one short string; sent when any axis moved by 0.03 or the stance changed (at most ~1/s)
function moodPushFace(chat, s) {
  if (!MOOD_CFG.faceLive || !MOOD_CFG.facePlugin) return;
  const r2 = x => Math.round(x * 100) / 100;
  const v = 'w=' + r2(s.w) + ' i=' + r2(s.i) + ' e=' + r2(s.e) + ' c=' + r2(s.c) + ' h=' + r2(s.h) + ' a=' + r2(s.a) + ' st=' + s.st;
  let last = null;
  try { last = JSON.parse(chat.get('face_pushed', 'null')); } catch (err) { last = null; }
  const moved = !last || last.st !== s.st || Math.abs(last.w - s.w) >= 0.03 || Math.abs(last.i - s.i) >= 0.03 || Math.abs(last.e - s.e) >= 0.03 ||
                Math.abs(last.c - s.c) >= 0.03 || Math.abs(last.h - s.h) >= 0.03 || Math.abs(last.a - s.a) >= 0.03;
  if (!moved) return;
  try {
    chat.appTrigger('String', MOOD_CFG.emotionAtom, MOOD_CFG.facePlugin, 'Mood', v);
    chat.set('face_pushed', JSON.stringify({ w: s.w, i: s.i, e: s.e, c: s.c, h: s.h, a: s.a, st: s.st }));
    moodLog('face told: ' + v);
  } catch (err) { moodLog('face send failed: ' + err); }
}
function facePushBool(chat, name, value) {
  if (!MOOD_CFG.faceLive || !MOOD_CFG.facePlugin) return;
  try { chat.appTrigger('Bool', MOOD_CFG.emotionAtom, MOOD_CFG.facePlugin, name, value); } catch (err) { moodLog('face send failed: ' + err); }
}

// the whole update, used by both entry points (userText: the user's message, args: a feeling the model or her own speech reports)
function moodUpdate(chat, args, userText, fn, herText) {
  const now = chat.time;
  let s = moodDecay(moodRead(chat, now), now);
  let heard = null, note = '';
  try { wardArousalSync(chat, s); } catch (err) { moodLog("wardrobe sync failed: " + err); }
  if (fn) fn(s, now);
  if (userText) { note = moodWaitingNote(chat, s, now); heard = moodAppraiseText(s, userText, now); try { agreeOnUser(chat, userText, now); agreeApply(chat, now); } catch (err) {} }
  if (herText) { const tone = moodReadHer(herText); if (tone) { moodApplyHer(s, tone); heard = 'her own tone: ' + tone; } }
  if (args) moodAppraiseFeeling(s, args, now);
  const before = s.st;
  moodFlags(s);
  s.st = moodStance(s);
  moodWrite(chat, s);
  // the action scripts read this to decide what movement fits how she feels right now
  try { chat.set('mood_stance', s.st); } catch (err) {}
  try { moodPushBody(chat, s, now); } catch (err) { moodLog('body mood push failed: ' + err); }
  const what = userText ? ('heard ' + (heard || 'nothing notable') + ' -> ') : (herText ? (heard || 'her tone: plain') + ' -> ' : (args ? 'feeling ' + JSON.stringify(args) + ' -> ' : 'refresh -> '));
  moodLog(what + moodSummary(s) + (before !== s.st ? '  [stance ' + before + ' -> ' + s.st + ']' : ''));
  moodApplyContext(chat, s);
  if (userText) moodNote(chat, note);     // a new message: last turn's note is over, a waiting note (if any) replaces it
  moodPushEmotion(chat, s);
  try { moodPushFace(chat, s); } catch (err) { moodLog('face push failed: ' + err); }
  return s;
}
// =================== END MOOD CORE ===================

// Standing rule for the model: the touch plugin's lines ("Todd kisses Ava.", "Todd touches Ava on the Breasts with His hand.") are
