  try { moodDebug('message role=' + (e && e.message ? e.message.role : '?') + ' sensor=' + isSensor(e) + ' text=' + String(e && e.message ? e.message.text : '').slice(0, 100)); } catch (err) {}
  if (isSensor(e)) {   // a touch / body message from the touch plugin: it moves arousal, and is never mistaken for something Todd said
    try { const tx = String(e.message.text || ''); moodUpdate(chat, null, null, (s, now) => moodTouch(chat, s, tx, now)); } catch (err) { console.log('MOOD touch failed: ' + err); }
    return;
  }
