  // testing: "mood test cold" puts her straight into a state so the voice / face / body can be checked without an evening of build-up.
  // The message still reaches the model (scripts cannot stop that), so do it in a lull. "mood test reset" clears it.
  try {
    const mt = /^\W*mood\s+test\s+(cold|guarded|hurt|withdrawn|furious|warm|aroused|tired|reset)\b/i.exec(String(e && e.message ? e.message.text : ''));
    if (mt) { moodTestPreset(chat, mt[1].toLowerCase()); return; }
  } catch (err) { console.log('MOOD test failed: ' + err); }
  try { moodUpdate(chat, null, e && e.message ? e.message.text : ''); } catch (err) { console.log('MOOD refresh failed: ' + err); }
  try { fastOnUser(chat, e && e.message ? String(e.message.text || '') : ''); } catch (err) { console.log('MOVE read failed: ' + err); }
});
function moodTestPreset(chat, which) {
  const P = {
    cold:      { i: 0.4, h: 0.1, w: 0.1, c: 0.6, e: 0.45, a: 0.05 },
    guarded:   { i: 0.4, h: 0.1, w: 0.1, c: 0.6, e: 0.45, a: 0.05 },
    hurt:      { i: 0.3, h: 0.6, w: 0.0, c: 0.4, e: 0.35, a: 0.0 },
    withdrawn: { i: 0.5, h: 0.5, w: -0.1, c: 0.3, e: 0.35, a: 0.0 },
    furious:   { i: 0.95, h: 0.3, w: -0.3, c: 0.3, e: 0.7, a: 0.0 },
    warm:      { i: 0.0, h: 0.0, w: 0.7, c: 0.9, e: 0.6, a: 0.12 },
    aroused:   { i: 0.0, h: 0.0, w: 0.6, c: 0.9, e: 0.6, a: 0.6, ht: 0.6 },
    tired:     { i: 0.0, h: 0.0, w: 0.3, c: 0.8, e: 0.12, a: 0.05 },
    reset:     null,
  };
  const preset = P[which];
  moodUpdate(chat, null, null, (st) => {
    if (!preset) { const b = MOOD_CFG.baseline; st.i = b.irritation; st.h = b.hurt; st.w = b.warmth; st.c = b.comfort; st.e = b.energy; st.a = b.arousal; st.ht = 0; st.L = []; st.r = 0; }
    else { for (const k of Object.keys(preset)) st[k] = preset[k]; }
    st.t = chat.time;
  });
  console.log('MOOD test preset: ' + which + ' -> ' + moodSummary(moodRead(chat, chat.time)));
}
chat.addEventListener("speechComplete", (e) => { facePushBool(chat, 'Speaking', false); });
chat.addEventListener("speechStart", (e) => {
