    try { const rt2 = e && e.message ? e.message.text : ''; if (moodReadHer(rt2)) moodUpdate(chat, null, null, null, rt2); } catch (err) { console.log('MOOD her tone failed: ' + err); }
    try { agreeOnReply(chat, e && e.message ? e.message.text : '', chat.time); } catch (err) { console.log('MOOD agreement failed: ' + err); }
    try { narrOnReply(chat, e && e.message ? e.message.text : ''); } catch (err) { console.log('NARR failed: ' + err); }
  });
} catch (err) { console.log('MOOD could not listen for finished replies: ' + err); }


// ---- WHAT DO THE OTHER EVENTS CARRY? Touch lines arrive as "Event" messages and never reach userMessageReceived (seen in the logs),
// so listen on the events that do fire, log what each one holds (first 40 only), and treat any touch-like message found there as touch.
function moodShape(e) {
  const out = { keys: [], message: null };
  try { out.keys = Object.keys(e || {}); } catch (err) {}
  try { if (e && e.message) out.message = { role: String(e.message.role), text: String(e.message.text || '').slice(0, 90), keys: Object.keys(e.message) }; } catch (err) {}
