// ===================== WARDROBE =====================
// Two paths. (1) Todd's own words clearly ask her to undress or dress: code reads the request and does it once she has answered
// without refusing (a refusal in her reply cancels it). (2) She decides on her own (a game she lost, a deal, the moment): the model calls
// take_off_clothing / put_on_clothing, which have NO arguments, so a garbled argument name can no longer lose the call.
const WARD_CFG = {
  enabled: true,
  plugin: 'plugin#4_Bplus.SmartWardrobe',
  atom: 'Person',
  pendingSeconds: 120,     // a request waits this long for her answer
  skipIfIrritation: 0.65,  // too angry with him to oblige
  order: ['Top', 'Bottom', 'Bra', 'Panties', 'Shoes'],  // what "a piece of clothing" takes off next
  log: true
