function wardLog(m) { if (WARD_CFG.log) console.log('WARDROBE ' + m); }

const WARD_PARTS = {
  top: 'Top', tops: 'Top', shirt: 'Top', blouse: 'Top', sweater: 'Top', jacket: 'Top', coat: 'Top', hoodie: 'Top',
  cardigan: 'Top', tank: 'Top', camisole: 'Top', tee: 'Top', jumper: 'Top',
  bottom: 'Bottom', bottoms: 'Bottom', skirt: 'Bottom', pants: 'Bottom', shorts: 'Bottom', jeans: 'Bottom',
  trousers: 'Bottom', leggings: 'Bottom',
  bra: 'Bra', bralette: 'Bra',
  panties: 'Panties', underwear: 'Panties', knickers: 'Panties', thong: 'Panties', undies: 'Panties', briefs: 'Panties',
  dress: 'Dress', gown: 'Dress',
  shoes: 'Shoes', boots: 'Shoes', heels: 'Shoes', sandals: 'Shoes', sneakers: 'Shoes',
  socks: 'Socks', stockings: 'Stockings', tights: 'Stockings', nylons: 'Stockings', pantyhose: 'Stockings'
