const WARD_ALL = /\b(?:everything|all (?:of )?(?:your|the) (?:clothes|clothing)|your (?:clothes|clothing|cloths)|naked|nude)\b/;
const WARD_NEXT = /\b(?:piece|pieces|item|items|article|something|anything|one more|another|next one|it off)\b/;
// her own announcement: "I'll remove my skirt", "fine, the shirt comes off", "there goes my top" - she said it, so the wardrobe does it
const WARD_HER_OWN = /\b(?:i'?ll|i will|i'?m going to|i'?m gonna|let me|i guess i'?ll|fine,? i'?ll|i suppose i'?ll|how about i|i could|i can)\s+(?:just\s+|slowly\s+)?(?:remove|take off|slip off|slide off|lose|ditch|shed|unbutton|unzip|unhook|strip off|pull off|kick off|peel off)\s+(?:my|the|this|these)\s+(\w+)|\b(?:there goes|off comes|off goes|say goodbye to)\s+(?:my|the)\s+(\w+)|\b(?:my|the)\s+(\w+)\s+(?:comes|is coming|goes|can go|can come)\s+off\b/;
const WARD_ADDRESSED = /\b(?:you|your|you'?re|youre|ya|yourself|yours)\b/;
const WARD_SELF = /\b(?:my|mine|i'?ll|i will|i'?m|i can|let me|i have to|i must|i'?d)\b/;
