const WARD_OFF = /\b(?:take|takes|taking|pull|pulling|slip|slide|peel|kick|throw|toss|get)\b[^.?!]{0,40}?\boff\b/;
const WARD_VERB = /\b(?:remove|removing|ditch|shed|strip|undress|disrobe|unbutton|unzip|unhook|unclasp)\b/;
