const WARD_OWE = /\bowe\b[^.?!]{0,30}\b(?:clothing|clothes|piece|item|article)\b/;
const WARD_START = /\b(?:start|begin) (?:with|by)\b/;
const WARD_DRESS = /\bget dressed\b|\bdress (?:up|yourself|again)\b|\bcover (?:up|yourself)\b|\bput (?:your |the |some |those )?(?:clothes|clothing|cloths) (?:back )?on\b|\bput (?:your |the |some )?(?:clothes|clothing|cloths) back\b/;
const WARD_PUTON = /\b(?:put|slip|pull|throw)\b[^.?!]{0,30}\bon\b/;
const WARD_MORE = /\b(?:see|show me|reveal|get) (?:a bit |a little |much |even )?more(?:[.,!?]|$| of (?:you\b(?! (?:art|work|music|story|stories|photos?|pictures?))|her\b|that|this|your (?:body|skin|figure|curves|legs|chest)))|\bsee the rest\b|\bthe rest of (?:you|it)\b/;
const WARD_REFUSE = /\b(?:no way|not a chance|nope|nah|not happening|not going to|not gonna|won'?t|will not|dream on|in your dreams|keep dreaming|forget it|forget about it|i'?d rather not|i refuse|not tonight|not yet|not so fast|not until|absolutely not|certainly not|over my dead|no,? (?:i|you|not|thanks|thank))\b|^\W*no\b(?! need| problem| worries| rush)/i;

function wardWords(t) { return String(t || '').toLowerCase().replace(/[^a-z]+/g, ' ').trim().split(' ').filter(w => w); }

// reads what Todd asked for: { state:'Undress'|'Dress', part:'Top'|...|'All'|'NEXT' } or null
function wardParse(text) {
  const parts = String(text || '').toLowerCase().replace(/[\u2018\u2019]/g, "'").split(/(?<=[.!?])\s+|\n+/);
  let found = null;
  for (const sentence of parts) {
    if (/\b(?:if|unless|whenever|suppose|would|could i|should i)\b/.test(sentence) && !/^\W*(?:now |ok |okay |please )*(?:take|remove|lose|strip|undress)\b/.test(sentence)) continue;
