}
function wardParseOne(raw) {
  if (!raw.trim()) return null;
  const words = wardWords(raw);
  let part = null;
  for (const w of words) { if (WARD_PARTS[w]) { part = WARD_PARTS[w]; break; } }
  const addressed = WARD_ADDRESSED.test(raw) || /^\W*(?:now |ok |okay |so |then |and |please |come on |go on )*(?:take|remove|lose|drop|strip|undress|slip|pull|get|unbutton|unzip|ditch|shed|put|pick|choose)\b/.test(raw)
    || /\b(?:another|next|one more|a second) (?:piece|item|article|one)\b[^.?!]{0,30}\b(?:remove|take off|off|lose|ditch)\b/.test(raw);
  if (!addressed) return null;
  if (WARD_SELF.test(raw) && !/\b(?:you|your|yours|yourself)\b/.test(raw)) return null;
  if (WARD_NEG.test(raw)) return null;
  const all = WARD_ALL.test(raw);
  // removing
  let remove = false;
  if (WARD_OFF.test(raw) || WARD_VERB.test(raw)) remove = true;
  else if (part) {
    // "lose the top", "start with your shirt"
    for (const m of raw.matchAll(/\b(?:lose|losing|drop|dropping)\b/g)) {
      if (raw.slice(m.index, m.index + 40).split(/\s+/).some(w => WARD_PARTS[w.replace(/[^a-z]/g, '')])) remove = true;
    }
    if (WARD_START.test(raw)) remove = true;
  }
  if (!remove && WARD_OWE.test(raw) && /\byou\b/.test(raw)) remove = true;
  const dressWords = WARD_DRESS.test(raw) || (WARD_PUTON.test(raw) && (part || all));
  if (remove && !(dressWords && !WARD_OFF.test(raw) && !WARD_VERB.test(raw))) {
    // "strip poker" is a game, not an order
    if (/\bstrip (?:poker|tease|club)\b/.test(raw) && !WARD_OFF.test(raw)) return null;
    if (part) return { state: 'Undress', part: part };
    if (all) return { state: 'Undress', part: 'All' };
    if (/\b(?:undress|disrobe|strip)\b/.test(raw)) return { state: 'Undress', part: 'All' };
    return { state: 'Undress', part: 'NEXT' };
  }
  if (dressWords) return { state: 'Dress', part: part || 'All' };
  return null;
}

function wardState(chat) {
  try { const s = JSON.parse(chat.get('cloth_state', '{}')); return (s && typeof s === 'object') ? s : {}; } catch (err) { return {}; }
}
function wardSave(chat, s) { try { chat.set('cloth_state', JSON.stringify(s)); } catch (err) {} }

// do it (explicit = Todd asked, so repeat even when she is believed to be in that state already)
function wardApply(chat, state, part) {
  const s = wardState(chat);
  let p = part;
  if (p === 'NAMED') {
    let named = []; try { named = JSON.parse(chat.get('ward_named', '[]')) || []; } catch (err) { named = []; }
    const todo = named.filter(x => s[x] !== 'Undress');
    if (todo.length) {
      for (const x of todo) wardApply(chat, state, x);
      return todo.join('+');
    }
    p = 'NEXT';
  }
  if (p === 'NEXT') {
    p = WARD_CFG.order.find(x => s[x] !== 'Undress') || null;
    if (!p) { wardLog('nothing left to take off'); return null; }
  }
  try { chat.appTrigger('StringChooser', WARD_CFG.atom, WARD_CFG.plugin, p + ' Control', state); }
  catch (err) { wardLog('send failed: ' + err); return null; }
  if (p === 'All') { for (const x of WARD_CFG.order) s[x] = state; } else { s[p] = state; }
  wardSave(chat, s);
  wardLog(state + ' ' + p);
  try { moodUpdate(chat, null, null); } catch (err) {}
  return p;
}

// Why it no longer waits for the audio to finish: speechComplete can arrive 30-80 s late when the TTS is slow (or never, when playback is
// not reported). The request is now decided on her first two sentences (a refusal in either cancels it) or when she finishes, whichever is first.
function wardDecide(chat, want, reply, why) {
  chat.set('cloth_intent', '');
  chat.set('reply_acc', '');
  chat.set('reply_n', 0);
  if (chat.time - want.t > WARD_CFG.pendingSeconds) { wardLog('request expired'); return; }
  if (WARD_REFUSE.test(reply.trim())) { wardLog('she refused, nothing done: ' + reply.trim().slice(0, 80)); return; }
  let angry = 0;
  try { const m = JSON.parse(chat.get('mood_state', '{}')); if (m && typeof m.i === 'number') angry = m.i; } catch (err) {}
  if (want.state === 'Undress' && angry >= WARD_CFG.skipIfIrritation) { wardLog('too angry with him, nothing done'); moodNote(chat, 'Todd asked her to undress; she is far too cross with him for that and says so'); return; }
  wardLog('deciding ' + why + ': ' + want.state + ' ' + want.part);
  wardApply(chat, want.state, want.part);
}

chat.addEventListener("userMessageReceived", (e) => {
  try {
    if (isSensor(e)) return;
    if (!WARD_CFG.enabled) return;
    const text = e && e.message ? e.message.text : '';
    chat.set('reply_acc', '');
    chat.set('reply_n', 0);
    const turn = (chat.get('ward_n', 0) | 0) + 1;
    chat.set('ward_n', turn);
    let want = wardParse(text);
