      const named = []; for (const w of wardWords(text)) { const p = WARD_PARTS[w]; if (p && named.indexOf(p) < 0) named.push(p); }
      if (named.length) chat.set('ward_named', JSON.stringify(named));
      if (want.part === 'NEXT' && /\b(?:them|those|both)\b/i.test(String(text || ''))) want.part = 'NAMED';
      if (want.state === 'Undress' && named.length > 1 && want.part !== 'All') want.part = 'NAMED';   // "shirt and shoes": both
      chat.set('cloth_intent', JSON.stringify(want));
      chat.set('cloth_req_n', turn);     // this turn's clothing is handled here: the model's own clothing actions stand aside for it
      wardLog('heard a request: ' + want.state + ' ' + want.part + ' <- ' + String(text).slice(0, 80));
    } else {
