// A movement agreed to over several messages ("I'd love to see you dance" ... "Yes please" ... "I'm waiting") stays
// open for the next few messages, so the dance is not thrown away because the last message holds no movement word.
const MOVE_WINDOW_MESSAGES = 4;
const MOVE_CUE_SHARED = /\b(?:stand|sit|walk|stroll|march|pace|dance|dancing|wave|spin|twirl|stretch|kneel|squat|crouch|bend|lean|toes|lie|lay|hug|pose|freeze|strut|sway|step|move|follow|show me|get up|get down|turn (?:around|away|back|to|left|right|over)|come (?:here|over|closer|to me|with me)|go (?:stand|sit|walk|over (?:there|here|to the))|back up|hold (?:it|that|still|there|the pose|position)|raise|lift|reach|point|clap|jump|hop|kick|bow|curtsy|curtsey|salute|nod|shake|wiggle|shimmy|twist|rotate|cross|fold|crawl|run|jog|skip|tiptoe|climb|rise|flex|lunge|stomp|tap|shrug|tilt|wink|spread|your (?:right |left )?(?:hand|hands|arm|arms|leg|legs|head|foot|feet|knee|knees|finger|fingers|shoulder|shoulders))\b/i;
