};
const FAST_AWAY = /\b(?:walk(?:s|ing)? (?:away|off|out)|leave|storm(?:s|ing)? off|turn(?:s|ing)? (?:away|(?:her|your) back)|step(?:s|ping)? (?:back|away)|back(?:s|ing)? away)\b/i;

const FAST_REPEAT = '(?:like )?i (?:just |already |clearly )?(?:said|told you to|told you|asked you to|asked)[ ,:]+(?:you )?(?:to )?';   // "I said kneel down": the user repeating a request
const FAST_LEAD = new RegExp('^[\\s,]*(?:(?:(?:ok|okay|so|now|and|then|alright|well|oh|hey|yes|yeah|sure|just)[ ,]+)|(?:' + FAST_REPEAT + '))+', 'i');
const FAST_FRAME = /\b(?:(?:like )?i (?:just |already |clearly )?(?:said|told you to|told you|asked you to)|please|pls|can you|could you|would you|will you|won'?t you|how about (?:you|we)|why don'?t you|what if you|let'?s see you|let me see you|i (?:want|wanna|would like|'?d like|'?d love|need) (?:you )?to see you|i (?:want|need|'?d like|would like) you to|show me|go ahead|you (?:should|could) (?:now )?|you(?:'ll| will| would)? (?:have|need|got) to |try to|time to|i'?m waiting|let'?s)\b/;
const FAST_VERB = /^[\s,]*(?:(?:ok|okay|so|now|and|then|alright|well|oh|hey|yes|yeah|sure|just|go ahead and)[ ,]+)*(?:please[ ,]+)?(?:stand|sit|walk|stroll|march|pace|dance|wave|spin|twirl|stretch|kneel|squat|crouch|bend|lean|lie|lay|hug|pose|freeze|strut|sway|step|move|follow|turn|come|go|back|hold|raise|lift|reach|point|clap|jump|hop|kick|bow|curtsy|curtsey|salute|nod|shake|wiggle|shimmy|twist|rotate|cross|fold|crawl|run|jog|skip|tiptoe|climb|rise|flex|lunge|stomp|tap|shrug|tilt|wink|spread|get (?:up|down|on)|put)\b/i;
const FAST_SKIP_Q = /^[\s,]*(?:what|why|where|when|who|which|how (?:much|many|long|far|come|was|is|are)|do you (?:like|love|enjoy|ever|usually|often|think|know|want to know)|did you|have you|are you (?:able|going|ok|okay)|is it|was it)\b/;

// pull the movement out of a sentence: "you will have to kneel to get them" -> "kneel", "sit down and I'll make us drinks" -> "sit down"
const FAST_HAVETO = /\byou(?:'ll| will| would)?\s+(?:have|need|got|has)\s+to\s+([^,.;!?]+)/i;
const FAST_TAIL = /\s*[,;]?\s*\b(?:and|but|so|because|while|then)\s+(?:i|i'll|i'm|i'd|we|we'll|we'd|let's|they|it|he|she|there)\b.*$/i;
