function fastClean(s) {
  let t = s.replace(FAST_LEAD, '');
  const h = t.match(FAST_HAVETO);
  if (h) t = h[1];
  t = t.replace(FAST_TAIL, '').replace(FAST_PURPOSE, '');
  return t.replace(/\bplease\b[ ,]*/gi, '').replace(/[.!?]+\s*$/, '').replace(/\s+/g, ' ').trim();
