// the movement the user asked for in this message ('' when there is none): only sentences that are asked of HER
function fastParse(text) {
  const out = [];
  const parts = String(text || '').replace(/[‘’]/g, "'").split(/(?<=[.!?])\s+|\n+/);
  const neg = new RegExp("\\b(?:don'?t|do not|dont|never|stop|no need to|not to|without)\\b[^.?!]{0,24}" + MOVE_CUE_SHARED.source, 'i');
  for (const raw of parts) {
    const sent = raw.trim();
    if (!sent) continue;
    const low = sent.toLowerCase();
    if (FAST_SKIP_Q.test(low)) continue;                 // a question about her, not a request
    if (!MOVE_CUE_SHARED.test(low)) continue;            // no movement word
    if (neg.test(low)) continue;                         // "don't sit"
    if (wardParse(low)) continue;                        // clothing is handled by the wardrobe code
    if (!(FAST_FRAME.test(low) || FAST_VERB.test(low))) continue;   // not phrased as a request
    if (/\b(?:i'?ll|i will|i'?m|i am|i can|i could|i would|i might|i have to|i must|i'?d)\b/.test(low) && !/\byou\b/.test(low) && !FAST_VERB.test(low)) continue; // about himself
    const c = fastClean(sent);
    if (c) out.push(c);
  }
  return out.join(', ');
}

function fastBlocked(stance, text) {
  return !!(FAST_BLOCK[stance] && FAST_BLOCK[stance].test(text) && !FAST_AWAY.test(text));
}

function fastSend(chat, text, why) {
  fastLog('-> Motion Request (' + why + '): ' + text);
  try {
    // her mood rides along (mood_style.py in the prompter): the same tag perform_action adds to the model's own movements
    let tagged = text;
    try { tagged = text + ' [mood stance=' + String(chat.get('mood_stance', 'engage')) + ' energy=' + String(chat.get('mood_energy', 'mid')) + ']'; } catch (err) {}
    chat.appTrigger('Bool', MOOD_CFG.emotionAtom, 'geometry', 'useAdvancedColliders', false);
    chat.appTrigger('String', MOOD_CFG.emotionAtom, MOOD_CFG.bvhPlugin, 'Motion Request', tagged);
    if (FAST_AWAY.test(text)) chat.set('leave_t', chat.time);   // the speech leave-sync must not repeat it
  } catch (err) { fastLog('send failed: ' + err); }
}

// called by the user-message listener AFTER the mood has been updated for this message
