            // not while she is cold toward him (then only pulling away), and not more often than OWN_MOVE_PAUSE seconds.
            const own = String((e.arguments && e.arguments.movement) || (e.arguments && e.arguments.prompt) || Object.keys(e.arguments || {}).map(k => e.arguments[k]).join(' ')).trim();
            const cold = (stance === 'disengage' || stance === 'withdrawn');
            if (!own) { console.log('perform_action: no movement given, nothing done'); return; }
            if (POLICY_ON && cold && !AWAY.test(own)) {
                console.log('perform_action: she is ' + stance + ', so she only pulls away on her own: ' + own);
                return;
            }
            // Walking somewhere is not something she can do on her own: she has no destination, so it would only be a pointless walk on the spot,
            // and the action model reads any mention of a plan ("shall we go for a hike?") as her walking off. Only pulling away is allowed (cold stances).
            if (LOCOMOTION.test(own) && !(cold && AWAY.test(own)) && !(!cold && APPROACH.test(own))) {
                console.log('perform_action: she is only talking about going somewhere, not walking off, so nothing is done: ' + own);
                return;
            }
            let last = -1e9;
            try { last = chat.get('own_move_t', -1e9); } catch (err) {}
            if (chat.time - last < OWN_MOVE_PAUSE) {
                console.log('perform_action: her own movement is too soon after the last one: ' + own);
                return;
            }
            try { chat.set('own_move_t', chat.time); } catch (err) {}
            console.log('perform_action: her own choice (' + stance + '): ' + own);
        }
    }
    try { chat.set('move_cue_left', 0); } catch (err) {}
    // The model often leaves the argument NAMES empty or empty-valued ({"name":"","value":"sit down"}), so e.arguments.prompt
    // is undefined. Recover in this order: the named argument, any non-empty argument value, then the movement sentences
    // of what the user actually said (so a request is never lost to a malformed call).
    const args = e.arguments || {};
    let prompt = String(args.prompt || '').trim();
    let style = String(args.style || '').trim();
    if (!prompt) {
        const vals = Object.keys(args).map(k => String(args[k] || '').trim()).filter(v => v && v !== style);
        if (vals.length) prompt = vals[0];
    }
    if (!prompt) {
        // last resort: a sentence the user addressed to HER ("you"/an imperative), reduced to the movement itself. Never a context sentence.
        let said2 = '';
        try { said2 = String(chat.get('user_last', '')); } catch (err) {}
        const ASKED = /^\W*(?:(?:ok|okay|so|now|and|then|please)[ ,]+)*(?:can you|could you|would you|will you|how about you|go ahead and|please)?\W*(?:stand|sit|walk|stroll|march|pace|dance|wave|spin|twirl|stretch|kneel|squat|crouch|bend|lean|lie|lay|hug|pose|freeze|strut|sway|step|move|follow|turn|come|go|back|hold|raise|lift|reach|point|clap|kick|bow|curtsy|nod|shake|wiggle|twist|crawl|run|jog|skip|tiptoe|climb|get up|get down)\b/i;
        const HAVETO = /\byou(?:'ll| will| would)?\s+(?:have|need|got)\s+to\s+([^,.;!?]+)/i;
        const cands = [];
        for (const sent of said2.split(/(?<=[.!?])\s+|\n+/)) {
            if (!MOVE_CUE.test(sent) || /\?\s*$/.test(sent)) continue;
            let t = sent;
            const h = t.match(HAVETO);
            if (h) t = h[1];
            else if (!(ASKED.test(t) || /\b(?:can|could|would|will|how about) you\b/i.test(t))) continue;
            t = t.replace(/\s*[,;]?\s*\b(?:and|but|so|because|while|then)\s+(?:i|i'll|i'm|i'd|we|we'll|let's|they|it|he|she|there)\b.*$/i, '')
                 .replace(/\s+(?:to get|to reach|to grab|to fetch|so that|so i|so we|in order|because)\b.*$/i, '')
                 .replace(/^\W*(?:(?:ok|okay|so|now|and|then)[ ,]+)*(?:please|can you|could you|would you|will you)[ ,]*/i, '')
                 .replace(/[.!?]+$/, '').trim();
            if (t) cands.push(t);
        }
        prompt = cands.join(', ');
        if (prompt) console.log('perform_action: the model sent no usable argument, using what the user asked: ' + prompt);
        else console.log('perform_action: the model sent no usable argument and the user asked nothing clear: nothing done');
    }
    // a style only makes sense for these; the model tends to add 'sexy' to everything
    if (!/danc|walk|wave|waving|stroll|march/i.test(prompt)) style = '';
    const text = (style && prompt.toLowerCase().indexOf(style.toLowerCase()) < 0) ? (prompt + ' ' + style).trim() : prompt;
    if (!text) return;
    // a scene note mistaken for a request, e.g. "a chair (close, ahead-left)": never a movement
    if (/[()]/.test(text) || /\b(ahead|behind)-(left|right)\b/i.test(text)) {
        console.log('perform_action: ignored a scene note: ' + text);
        return;
    }
    if (POLICY_ON && POLICY_BLOCK[stance] && POLICY_BLOCK[stance].test(text) && !AWAY.test(text)) {
        console.log('perform_action: she is ' + stance + ', so she does not do this for him: ' + text);
        return;
    }
    if (AWAY.test(text)) { try { chat.set('leave_t', chat.time); } catch (err) {} }  // do not let the speech leave-sync repeat it
    chat.appTrigger('Bool', 'Person', 'geometry', 'useAdvancedColliders', false);
    // how she feels rides along as a tag the prompter strips and uses (mood_style.py): a guarded walk is slower, arms crossed
    let tagged = text;
    try { tagged = text + ' [mood stance=' + stance + ' energy=' + String(chat.get('mood_energy', 'mid')) + ']'; } catch (err) {}
    chat.appTrigger('String', 'Person', 'plugin#1_ElkVR.BVHPlayer', 'Motion Request', tagged);
}

import { chat } from "@voxta";

// She decides this herself (a game she lost, a deal, a dare, the moment). One call, one 'part' argument.
// The model can garble the argument, so the code reads any value that names a piece and otherwise takes the next piece she still wears.
// Limits: one piece per turn, a pause between pieces, and only while she is relaxed toward him (engage/playful, not irritated, comfortable).
const PLUGIN = 'plugin#4_Bplus.SmartWardrobe';
const PARTS = ['Top', 'Bottom', 'Bra', 'Panties', 'Shoes'];
const ORDER = ['Top', 'Bottom', 'Shoes', 'Bra', 'Panties'];   // used when the model names nothing usable
const ALIASES = { top: 'Top', shirt: 'Top', jacket: 'Top', blouse: 'Top', bottom: 'Bottom', bottoms: 'Bottom', skirt: 'Bottom', pants: 'Bottom', shorts: 'Bottom',
  bra: 'Bra', panties: 'Panties', underwear: 'Panties', shoes: 'Shoes', boots: 'Shoes', shoe: 'Shoes' };
const PAUSE = 25;        // seconds between pieces she takes off on her own
const MAX_IRRITATION = 0.35, MIN_COMFORT = 0.5;

export function trigger(e) {
  const turn = chat.get('ward_n', 0);
  if (chat.get('cloth_req_n', -1) === turn) { console.log('take_off_clothing: this turn\'s request is handled by the wardrobe code'); return; }
  if (chat.get('cloth_own_n', -1) === turn) { console.log('take_off_clothing: already did one this turn'); return; }
  let stance = 'engage';
  try { stance = String(chat.get('mood_stance', 'engage')); } catch (err) {}
  let m = {};
  try { m = JSON.parse(chat.get('mood_state', '{}')) || {}; } catch (err) {}
  if (stance !== 'engage' && stance !== 'playful') { console.log('take_off_clothing: she is ' + stance + ', so she does not'); return; }
  if ((m.i || 0) >= MAX_IRRITATION || (m.c !== undefined && m.c < MIN_COMFORT)) { console.log('take_off_clothing: she is not at ease right now'); return; }
  if (chat.time - chat.get('cloth_own_t', -1e9) < PAUSE) { console.log('take_off_clothing: too soon after the last piece'); return; }
  let seen = {};
  try { seen = JSON.parse(chat.get('cloth_state', '{}')) || {}; } catch (err) { seen = {}; }
  // Her own choice (nobody asked) must be something she actually said: "let me give you something to enjoy", "watch this".
  // The action model otherwise picks take_off_clothing on any flirty line ("Maybe. Depends on what you had in mind." cost her the skirt).
  let said = '', reply = '';
  try { said = String(chat.get('user_last', '') || ''); } catch (err) {}
  try { reply = String(chat.get('reply_last', '') || ''); } catch (err) {}
  const ASKED = /\b(?:take (?:it|that|them|this|your \w+|off)|take off|strip|undress|get naked|lose the|out of (?:your|that|those)|show me (?:your|those|that|what)|remove|slip (?:out of|off)|unhook|unbutton|unzip|unclasp|peel)\b/i;
  const ANNOUNCED = /\b(?:take (?:this|it|that|them|my \w+) off|take off|strip\w*|undress\w*|slip (?:out of|off|this)|unhook|unbutton|unzip|unclasp|peel|lose (?:the|this|my)|something to (?:really )?enjoy|watch (?:this|closely|me)|show you|a (?:little |real )?show|get (?:more )?comfortable|too hot|feeling hot|bare|naked|nude|skin)\b/i;
  if (!ASKED.test(said) && !ANNOUNCED.test(reply)) {
    console.log('take_off_clothing: nobody asked and she did not say she would (user: "' + said.slice(0, 50) + '" / her: "' + reply.slice(0, 50) + '"), so she keeps it on');
    return;
  }
  // the model sometimes leaves the argument name empty or wrong: take the first value that names a piece
  const a = e.arguments || {};
  let part = null;
  for (const v of [a.part].concat(Object.keys(a).map(k => a[k]))) {
    const w = String(v || '').trim().toLowerCase().replace(/[^a-z]/g, '');
    let hit = ALIASES[w];
    if (!hit) {   // run-together or extra words ("skirtbelt", "theshirt"): the longest piece name inside it, 4+ letters so 'bra' never matches 'bracelet'
      const k = Object.keys(ALIASES).filter(x => x.length >= 4 && w.indexOf(x) >= 0).sort((p, q) => q.length - p.length)[0];
      if (k) hit = ALIASES[k];
    }
    if (hit) { part = hit; break; }
  }
  if (part && seen[part] === 'Undress') { console.log('take_off_clothing: ' + part + ' is already off, taking the next piece instead'); part = null; }
  if (!part) {
    // the model named nothing usable: the piece the dialogue names ("take off my bra completely") comes before the default order
    const words = (said + ' ' + reply).toLowerCase().match(/[a-z]+/g) || [];
    for (const w of words) { if (ALIASES[w] && seen[ALIASES[w]] !== 'Undress') { part = ALIASES[w]; break; } }
    if (part) console.log('take_off_clothing: no usable piece in ' + JSON.stringify(e.arguments) + ', the dialogue names the ' + part);
  }
  if (!part) {
    part = ORDER.find(p => seen[p] !== 'Undress');
    if (!part) { console.log('take_off_clothing: nothing left to take off'); return; }
    console.log('take_off_clothing: no usable piece in ' + JSON.stringify(e.arguments) + ', taking ' + part);
  }
  chat.appTrigger('StringChooser', 'Person', PLUGIN, part + ' Control', 'Undress');
  seen[part] = 'Undress';
  chat.set('cloth_state', JSON.stringify(seen));
  chat.set('cloth_own_n', turn);
  chat.set('cloth_own_t', chat.time);
  console.log('take_off_clothing: her own choice -> Undress ' + part);
}

import { chat } from "@voxta";

// She decides to get dressed again (cold, embarrassed, upset, or asked to). No arguments: the code puts everything back on.
const PLUGIN = 'plugin#4_Bplus.SmartWardrobe';

export function trigger(e) {
  const turn = chat.get('ward_n', 0);
  if (chat.get('cloth_req_n', -1) === turn) { console.log('put_on_clothing: this turn\'s request is handled by the wardrobe code'); return; }
  let seen = {};
  try { seen = JSON.parse(chat.get('cloth_state', '{}')) || {}; } catch (err) { seen = {}; }
  if (!Object.keys(seen).some(k => seen[k] === 'Undress')) { console.log('put_on_clothing: she is already dressed'); return; }
  chat.appTrigger('StringChooser', 'Person', PLUGIN, 'All Control', 'Dress');
  for (const k of Object.keys(seen)) seen[k] = 'Dress';
  chat.set('cloth_state', JSON.stringify(seen));
  chat.set('cloth_own_n', turn);
  console.log('put_on_clothing: her own choice -> Dress all');
}

import { chat } from "@voxta";

// Exactly as the SmartWardrobe "Change Outfit" dropdown shows them. Add the rest of your presets.
const OUTFITS = ['Fully_dressed', 'Lewd_A', 'lewd_B', 'Fulley_lewd', 'Nude_A'];
const clean = s => String(s || '').trim().toLowerCase().replace(/\.vap$/, '').replace(/^preset_/, '');

export function trigger(e) {
  // the model sometimes leaves the argument name empty or wrong: take the first value that is an outfit
  const vals = [e.arguments && e.arguments.outfit].concat(Object.keys(e.arguments || {}).map(k => e.arguments[k]));
  let match = null;
  for (const v of vals) { match = OUTFITS.find(o => clean(o) === clean(v)); if (match) break; }
  if (!match) {
    console.log('change_outfit: no known outfit in ' + JSON.stringify(e.arguments) + ', ignored');
    return;
  }
  chat.appTrigger('StringChooser', 'Person', 'plugin#4_Bplus.SmartWardrobe', 'All Control', 'Dress');
  chat.appTrigger('StringChooser', 'Person', 'plugin#4_Bplus.SmartWardrobe', 'Change Outfit', match);
  // keep the wardrobe memory in step with what the preset leaves her wearing
  const LEFT = { fully_dressed: { Top: 'Dress', Bottom: 'Dress', Bra: 'Dress', Panties: 'Dress' },
                 nude_a: { Top: 'Undress', Bottom: 'Undress', Bra: 'Undress', Panties: 'Undress' },
                 fulley_lewd: { Top: 'Undress', Bottom: 'Undress', Bra: 'Undress', Panties: 'Undress' },
                 lewd_a: { Top: 'Dress', Bottom: 'Dress', Bra: 'Undress', Panties: 'Dress' } };
  const st = LEFT[clean(match)];
  if (st) { try { chat.set('cloth_state', JSON.stringify(st)); } catch (err) {} }
}
